import os
from mindee import Client, TypeInvoiceV4
from mindee.exceptions import MindeeError

def extract_invoice_fields(image_path):
    """
    Extract structured fields from an invoice using Mindee's Invoice OCR API.

    Args:
        image_path (str): Path to the invoice image file

    Returns:
        dict: Extracted invoice data with validation
    """
    # Initialize Mindee client with API key from environment
    mindee_client = Client(api_key=os.getenv("MINDEE_API_KEY"))

    # Load and parse the document
    input_doc = mindee_client.source_from_path(image_path)
    result = mindee_client.parse(TypeInvoiceV4, input_doc)

    # Extract invoice data
    invoice = result.document.inference.prediction

    # Validate required fields and confidence scores
    required_fields = [
        'invoice_number',
        'date',
        'due_date',
        'total_amount',
        'supplier_name'
    ]

    validated_data = {}

    # Check required fields and their confidence scores
    for field in required_fields:
        if hasattr(invoice, field) and getattr(invoice, field):
            field_value = getattr(invoice, field)
            confidence = getattr(field_value, 'confidence', 0.0)

            # Validate confidence score (minimum 0.8)
            if confidence >= 0.8:
                validated_data[field] = {
                    'value': field_value.value,
                    'confidence': confidence
                }
            else:
                validated_data[field] = {
                    'value': field_value.value,
                    'confidence': confidence,
                    'warning': 'Low confidence score'
                }
        else:
            validated_data[field] = {'error': 'Missing required field'}

    # Add additional fields
    validated_data['supplier_address'] = {
        'value': getattr(invoice.supplier_address, 'value', None),
        'confidence': getattr(getattr(invoice.supplier_address, 'confidence', None), 'value', 0.0)
    } if hasattr(invoice, 'supplier_address') else {'error': 'Missing supplier address'}

    validated_data['customer_name'] = {
        'value': getattr(invoice.customer_name, 'value', None),
        'confidence': getattr(getattr(invoice.customer_name, 'confidence', None), 'value', 0.0)
    } if hasattr(invoice, 'customer_name') else {'error': 'Missing customer name'}

    return validated_data

